"""Rebuild the product composition from OpenVid's public sample artwork."""
from pathlib import Path
import html, json

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / 'brag-output/composition'
source = json.loads((ROOT/'examples/business/press.json').read_text())['document']
esc = html.escape


def canvas(scene, prefix):
    result = []
    for i, layer in enumerate(scene['layers']):
        if layer['kind'] == 'audio' or layer.get('caption') or layer.get('hidden'):
            continue
        style = f"left:{layer['x']}%;top:{layer['y']}%;width:{layer['w']}%;height:{layer['h']}%;opacity:{layer['opacity']};"
        content = ''
        if layer['kind'] == 'text':
            style += f"color:{layer['color']};font-size:{layer['fontSize']/2}px;font-weight:{700 if layer['bold'] else 400};text-align:{layer['align']};white-space:pre-wrap;line-height:1.08;"
            content = esc(layer['text'])
        elif layer['kind'] == 'shape':
            style += f"background:{layer['fill']};border-radius:{layer.get('radius',0)/2}px;"
        elif layer['kind'] == 'image':
            content = f'<img alt="Aurelia sample photograph" src="assets/{Path(layer["url"]).name}" style="width:100%;height:100%;object-fit:cover">'
        else:
            continue
        result.append(f'<div id="{prefix}-layer-{i}" class="sample-layer" style="{style}">{content}</div>')
    return ''.join(result)

sample1 = canvas(source['scenes'][0], 'opening')
sample2 = canvas(source['scenes'][1], 'chart')
cards = ''.join(f'<article class="example-card" id="example-{i}"><img src="assets/{key}.jpg" alt="{label} example"><div><span class="example-num">0{i+1}</span><strong>{label}</strong></div></article>' for i,(key,label) in enumerate([('press','Press announcement'),('launch','Product launch'),('results','Quarterly results'),('sales','Sales presentation'),('customer','Customer story'),('strategy','Team strategy')]))
audio = json.loads((OUT/'assets/audio-data.json').read_text())
# Precomputed per-frame keyframes: no render-time audio analysis or clocks.
energy = json.dumps([round(f['rms'],4) for f in audio['frames']])
